ALTER TABLE public.posts ADD COLUMN IF NOT EXISTS video_url text;
ALTER TABLE public.posts ADD COLUMN IF NOT EXISTS video_path text;
ALTER TABLE public.post_comments ADD COLUMN IF NOT EXISTS parent_id uuid REFERENCES public.post_comments(id) ON DELETE CASCADE;
ALTER TABLE public.story_comments ADD COLUMN IF NOT EXISTS parent_id uuid REFERENCES public.story_comments(id) ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS post_comments_parent_idx ON public.post_comments(parent_id);
CREATE INDEX IF NOT EXISTS story_comments_parent_idx ON public.story_comments(parent_id);
CREATE TABLE IF NOT EXISTS public.comment_reactions (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, post_comment_id uuid REFERENCES public.post_comments(id) ON DELETE CASCADE, story_comment_id uuid REFERENCES public.story_comments(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), CHECK (num_nonnulls(post_comment_id,story_comment_id)=1));
CREATE UNIQUE INDEX IF NOT EXISTS comment_reactions_post_unique ON public.comment_reactions(user_id,post_comment_id);
CREATE UNIQUE INDEX IF NOT EXISTS comment_reactions_story_unique ON public.comment_reactions(user_id,story_comment_id);
ALTER TABLE public.comment_reactions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS comment_reactions_read ON public.comment_reactions;
CREATE POLICY comment_reactions_read ON public.comment_reactions FOR SELECT TO authenticated USING(true);
DROP POLICY IF EXISTS comment_reactions_insert ON public.comment_reactions;
CREATE POLICY comment_reactions_insert ON public.comment_reactions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
DROP POLICY IF EXISTS comment_reactions_delete ON public.comment_reactions;
CREATE POLICY comment_reactions_delete ON public.comment_reactions FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE IF NOT EXISTS public.social_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, actor_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('comment','reply','comment_like')), target_type text NOT NULL CHECK(target_type IN ('post','story')), target_id uuid NOT NULL, comment_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.social_activity ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS social_activity_read ON public.social_activity;
CREATE POLICY social_activity_read ON public.social_activity FOR SELECT TO authenticated USING(recipient_id=auth.uid());
CREATE INDEX IF NOT EXISTS social_activity_recipient_idx ON public.social_activity(recipient_id,created_at DESC);
GRANT SELECT,INSERT,DELETE ON public.comment_reactions TO authenticated;
GRANT SELECT ON public.social_activity TO authenticated;
CREATE OR REPLACE FUNCTION public.validate_comment_parent() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE parent_target uuid; BEGIN IF NEW.parent_id IS NOT NULL THEN IF TG_TABLE_NAME='post_comments' THEN SELECT post_id INTO parent_target FROM public.post_comments WHERE id=NEW.parent_id; IF parent_target IS DISTINCT FROM NEW.post_id THEN RAISE EXCEPTION 'Reply must belong to the same post'; END IF; ELSE SELECT story_id INTO parent_target FROM public.story_comments WHERE id=NEW.parent_id; IF parent_target IS DISTINCT FROM NEW.story_id THEN RAISE EXCEPTION 'Reply must belong to the same story'; END IF; END IF; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS validate_reply_parent ON public.post_comments;
CREATE TRIGGER validate_reply_parent BEFORE INSERT OR UPDATE ON public.post_comments FOR EACH ROW EXECUTE FUNCTION public.validate_comment_parent();
DROP TRIGGER IF EXISTS validate_reply_parent ON public.story_comments;
CREATE TRIGGER validate_reply_parent BEFORE INSERT OR UPDATE ON public.story_comments FOR EACH ROW EXECUTE FUNCTION public.validate_comment_parent();
CREATE OR REPLACE FUNCTION public.create_social_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE recipient uuid; target uuid; comment_uuid uuid; target_kind text; event_kind text; BEGIN IF TG_TABLE_NAME='comment_reactions' THEN event_kind:='comment_like'; IF NEW.post_comment_id IS NOT NULL THEN SELECT user_id,post_id,id INTO recipient,target,comment_uuid FROM public.post_comments WHERE id=NEW.post_comment_id; target_kind:='post'; ELSE SELECT user_id,story_id,id INTO recipient,target,comment_uuid FROM public.story_comments WHERE id=NEW.story_comment_id; target_kind:='story'; END IF; ELSE comment_uuid:=NEW.id; event_kind:=CASE WHEN NEW.parent_id IS NULL THEN 'comment' ELSE 'reply' END; IF TG_TABLE_NAME='post_comments' THEN target:=NEW.post_id; target_kind:='post'; SELECT user_id::uuid INTO recipient FROM public.posts WHERE id=target; ELSE target:=NEW.story_id; target_kind:='story'; SELECT user_id::uuid INTO recipient FROM public.stories WHERE id=target; END IF; IF recipient IS NOT NULL AND recipient<>NEW.user_id THEN INSERT INTO public.social_activity(recipient_id,actor_id,kind,target_type,target_id,comment_id) VALUES(recipient,NEW.user_id,event_kind,target_kind,target,comment_uuid); END IF; IF NEW.parent_id IS NULL THEN RETURN NEW; END IF; IF TG_TABLE_NAME='post_comments' THEN SELECT user_id INTO recipient FROM public.post_comments WHERE id=NEW.parent_id; ELSE SELECT user_id INTO recipient FROM public.story_comments WHERE id=NEW.parent_id; END IF; END IF; IF recipient IS NOT NULL AND recipient<>NEW.user_id AND NOT EXISTS(SELECT 1 FROM public.social_activity WHERE comment_id=comment_uuid AND actor_id=NEW.user_id AND recipient_id=recipient AND kind=event_kind) THEN INSERT INTO public.social_activity(recipient_id,actor_id,kind,target_type,target_id,comment_id) VALUES(recipient,NEW.user_id,event_kind,target_kind,target,comment_uuid); END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS notify_comment ON public.post_comments;
CREATE TRIGGER notify_comment AFTER INSERT ON public.post_comments FOR EACH ROW EXECUTE FUNCTION public.create_social_activity();
DROP TRIGGER IF EXISTS notify_comment ON public.story_comments;
CREATE TRIGGER notify_comment AFTER INSERT ON public.story_comments FOR EACH ROW EXECUTE FUNCTION public.create_social_activity();
DROP TRIGGER IF EXISTS notify_comment ON public.comment_reactions;
CREATE TRIGGER notify_comment AFTER INSERT ON public.comment_reactions FOR EACH ROW EXECUTE FUNCTION public.create_social_activity();
REVOKE ALL ON FUNCTION public.create_social_activity() FROM PUBLIC;
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES('post-videos','post-videos',false,104857600,ARRAY['video/mp4','video/webm','video/quicktime','video/3gpp','video/x-m4v']) ON CONFLICT(id) DO NOTHING;
DROP POLICY IF EXISTS post_videos_read ON storage.objects;
CREATE POLICY post_videos_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='post-videos');
DROP POLICY IF EXISTS post_videos_insert ON storage.objects;
CREATE POLICY post_videos_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='post-videos' AND (storage.foldername(name))[1]=auth.uid()::text);
DROP POLICY IF EXISTS post_videos_delete ON storage.objects;
CREATE POLICY post_videos_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='post-videos' AND (storage.foldername(name))[1]=auth.uid()::text);